actions.input:
{ scheduleName: string, 
/**
 * Kept only in RivetKit's durable schedule payload, never in public job
 * metadata. A raw actor action call cannot forge a scheduled invocation.
 */
invokeToken: string, command: string, args: Array<string>, options: ActorSpawnOptions, configRevision: number | bigint, }

types.declaration:
type RemotePackageSourceInput = { url: string, digest: string | null, 
/**
 * Resolution metadata is accepted so a `config.get` snapshot can be sent
 * back to `config.set`. Core re-resolves the source and never trusts it.
 */
sizeBytes: bigint | null, packageId: string | null, };

type VmGroupConfig = { gid: number, name: string, 
/**
 * Authoritative `/etc/group` membership. Process supplementary gids are
 * intentionally not merged into this list.
 */
members: Array<string>, };

type VmUserAccountConfig = { uid: number, gid: number, username: string, homedir: string, shell: string, gecos?: string, 
/**
 * Initial process credentials only. These gids do not add the account to
 * an explicit `/etc/group` record's member list.
 */
supplementaryGids: Array<number>, };

type VmUserConfig = { uid?: number, gid?: number, euid?: number, egid?: number, username?: string, homedir?: string, shell?: string, gecos?: string, groupName?: string, 
/**
 * Initial supplementary process credentials. An explicit group record is
 * authoritative and is not given extra members from this list.
 */
supplementaryGids?: Array<number>, accounts?: Array<VmUserAccountConfig>, groups?: Array<VmGroupConfig>, };
